local LinenRetter = {}
local PRODUCTS = {
    retted_straw = { name = "Razmočeno slamo", flaxStalkCost = 2, waterCost = 2, time = 2, cost = 14, quality = 30, description = "Razmočeno slamo za ločevanje vlaken." },
    broken_fiber = { name = "Lomljena vlakna", flaxStalkCost = 3, waterCost = 2, time = 4, cost = 38, quality = 50, prestige = 1, description = "Lomljena lanena vlakna." },
    scutched_flax = { name = "Tolčeni lan", flaxStalkCost = 3, waterCost = 2, time = 5, cost = 85, quality = 65, prestige = 2, happiness = 1, description = "Tolčeni lan za predenje." },
    hackled_line = { name = "Česan lan", flaxStalkCost = 4, waterCost = 2, oilCost = 1, time = 7, cost = 200, quality = 80, prestige = 5, happiness = 2, description = "Česan lan za fine niti." },
    silver_tow_line = { name = "Srebrni kuclji lan", flaxStalkCost = 5, silverCost = 1, waterCost = 2, oilCost = 1, time = 10, cost = 460, quality = 92, prestige = 11, happiness = 3, description = "Lan s srebrnimi kuclji za plemiče." },
    royal_grand_line = { name = "Kraljevski veliki lan", flaxStalkCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, waterCost = 3, oilCost = 1, time = 15, cost = 1500, quality = 100, prestige = 35, happiness = 8, description = "Veliki kraljevski lan z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Lanarska delavnica", cost = { gold = 260, wood = 130, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    retting_pond = { name = "Močilnik", cost = { gold = 850, wood = 250, stone = 350, water = 10 }, upkeep = 20, qualityBonus = 18 },
    breaking_house = { name = "Lomilnica", cost = { gold = 2100, wood = 350, stone = 600, silver = 30, flax = 8 }, upkeep = 52, qualityBonus = 30 },
    royal_linen_atelier = { name = "Kraljevski atelje lana", cost = { gold = 8500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 170, qualityBonus = 55, prestigeBonus = 40 },
}
LinenRetter.flaxStalkStock = 22; LinenRetter.waterStock = 18; LinenRetter.oilStock = 12; LinenRetter.silverStock = 8; LinenRetter.goldStock = 6; LinenRetter.jewelStock = 6
LinenRetter.productStock = {}; LinenRetter.buildings = {}; LinenRetter.maker = nil; LinenRetter.activeMaking = {}; LinenRetter.totalProducts = 0; LinenRetter.dayTimer = 0
function LinenRetter.init() LinenRetter.flaxStalkStock=22; LinenRetter.waterStock=18; LinenRetter.oilStock=12; LinenRetter.silverStock=8; LinenRetter.goldStock=6; LinenRetter.jewelStock=6; LinenRetter.productStock={}; LinenRetter.buildings={}; LinenRetter.maker=nil; LinenRetter.activeMaking={}; LinenRetter.totalProducts=0; LinenRetter.dayTimer=0; print("[LinenRetter] Royal Linen Retter System initialized (6 products, 4 buildings)") end
function LinenRetter.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LinenRetter.maker={name=n or ("Lanar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lanar najet: %s (spretnost: %d)",LinenRetter.maker.name,s),"success") end; return true end
function LinenRetter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LinenRetter.build(id) local ok,e=LinenRetter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LinenRetter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LinenRetter.getQualityBonus() local b=0; for _,bd in ipairs(LinenRetter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LinenRetter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.flaxStalkCost and LinenRetter.flaxStalkStock<(d.flaxStalkCost or 0) then return false,"Premalo lanovih stebel" end; if d.waterCost and LinenRetter.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.oilCost and LinenRetter.oilStock<(d.oilCost or 0) then return false,"Premalo olja" end; if d.silverCost and LinenRetter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LinenRetter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LinenRetter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #LinenRetter.buildings==0 then return false,"Potrebna delavnica" end; if not LinenRetter.maker then return false,"Potreben lanar" end; return true end
function LinenRetter.make(pt,qty) qty=qty or 5; local ok,e=LinenRetter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.flaxStalkCost then LinenRetter.flaxStalkStock=LinenRetter.flaxStalkStock-d.flaxStalkCost*qty end; if d.waterCost then LinenRetter.waterStock=LinenRetter.waterStock-d.waterCost*qty end; if d.oilCost then LinenRetter.oilStock=LinenRetter.oilStock-d.oilCost*qty end; if d.silverCost then LinenRetter.silverStock=LinenRetter.silverStock-d.silverCost*qty end; if d.goldCost then LinenRetter.goldStock=LinenRetter.goldStock-d.goldCost*qty end; if d.jewelCost then LinenRetter.jewelStock=LinenRetter.jewelStock-d.jewelCost*qty end; local t=d.time; if LinenRetter.maker then t=math.max(1,t-math.floor(LinenRetter.maker.skill/12)) end; table.insert(LinenRetter.activeMaking,{id="linen_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LinenRetter.completeMaking(m) local q=1.0+(LinenRetter.getQualityBonus()/100); if LinenRetter.maker then q=q+(LinenRetter.maker.skill/180) end; q=math.min(2.0,q); LinenRetter.productStock[m.productType]=(LinenRetter.productStock[m.productType] or 0)+m.quantity; LinenRetter.totalProducts=LinenRetter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LinenRetter.maker then LinenRetter.maker.itemsMade=LinenRetter.maker.itemsMade+m.quantity; if math.random()<0.20 then LinenRetter.maker.skill=math.min(100,LinenRetter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lan izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"linen.completed",{productName=m.productName,quality=m.quality}) end end
function LinenRetter.update(dt) if not _G.state then return end; LinenRetter.dayTimer=LinenRetter.dayTimer+dt; if LinenRetter.dayTimer>=30 then LinenRetter.dayTimer=0; for i=#LinenRetter.activeMaking,1,-1 do local m=LinenRetter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LinenRetter.completeMaking(m); table.remove(LinenRetter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LinenRetter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LinenRetter.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LinenRetter.getStats() return {flaxStalkStock=LinenRetter.flaxStalkStock,waterStock=LinenRetter.waterStock,oilStock=LinenRetter.oilStock,silverStock=LinenRetter.silverStock,goldStock=LinenRetter.goldStock,jewelStock=LinenRetter.jewelStock,productStock=LinenRetter.productStock,numBuildings=#LinenRetter.buildings,hasMaker=LinenRetter.maker~=nil,makerName=LinenRetter.maker and LinenRetter.maker.name or "—",makerSkill=LinenRetter.maker and LinenRetter.maker.skill or 0,activeMaking=#LinenRetter.activeMaking,totalProducts=LinenRetter.totalProducts} end
return LinenRetter
